import { rm } from 'node:fs/promises';
import { resolve, relative } from 'node:path';
const project=process.cwd();
const target=resolve(project,'.netlify-api','runtime');
if(relative(project,target)!=='.netlify-api/runtime'&&relative(project,target)!=='.netlify-api\\runtime')throw new Error('Destino de build inválido.');
// Only the disposable dependency package generated by this build; never source or database files.
rm(target,{recursive:true,force:true}).catch(()=>{console.error('Não foi possível limpar o pacote temporário da API.');process.exitCode=1;});
